"""Runtime support for vecDSL programs generated for Vespa, over its HTTP APIs with the Python standard library. Generated by
vecDSL 7. Do not edit.

Every statement arrives as application package files, YQL texts and query request bodies built by the generator, identical in the
Python, TypeScript and Java programs; values travel as request parameters that the YQL references with @name, never inside the YQL
text. DDL statements deploy the whole package through the deploy API of the config server and wait until the application has
converged and serves queries; writes go through document/v1 with the document id id:vecdsl:<type>::<key>; reads use the query API.
"""

from __future__ import annotations

import datetime
import hashlib
import io
import json
import math
import os
import time
import urllib.error
import urllib.parse
import urllib.request
import zipfile
from decimal import Decimal
from typing import Any, NoReturn, Sequence

NAMESPACE = "vecdsl"
CLUSTER = "vecdsl"
EXPIRES = "vecdsl_expires"
VERSION = "vecdsl_version"
NO_EXPIRY = 253402300799
_DIGITS = 6
_PAGE = 1000
HIGHLIGHT = "vecdsl_hl_"
BOLD = "<hi>"
_DEPLOY_TIMEOUT = 600.0
_READY_TIMEOUT = 300.0
_POLL = 2.0
_RETRY_TIMEOUT = 60.0
_UNTIL = "{" + "{until}}"
_APPLICATION = "/application/v2/tenant/default/application/default"
_INSTANCE = _APPLICATION + "/environment/prod/region/default/instance/default"


class UnsupportedFeature(NotImplementedError):
    pass


class ConflictError(RuntimeError):
    pass


class VespaError(RuntimeError):
    def __init__(self, message: str, status: int | None = None) -> None:
        super().__init__(message)
        self.status = status


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


# ---------------------------------------------------------------- values


def plain(value: float) -> str:
    """A number as text in one form for every host language: integers without a fraction, others in plain decimal notation."""
    if isinstance(value, bool):
        raise TypeError("a boolean is not a number")
    if float(value).is_integer() and abs(value) < 1e15:
        return str(int(value))
    text = format(Decimal(repr(float(value))), "f")
    return text.rstrip("0").rstrip(".") if "." in text else text


def dumps(value: Any) -> str:
    """Compact JSON with numbers written by plain(), so that the three runtimes send identical bodies."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        if isinstance(value, float) and not math.isfinite(value):
            raise ValueError("JSON has no infinite or NaN numbers")
        return plain(value)
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, dict):
        return "{" + ",".join(json.dumps(str(key), ensure_ascii=False) + ":" + dumps(item) for key, item in value.items()) + "}"
    if isinstance(value, (list, tuple)):
        return "[" + ",".join(dumps(item) for item in value) + "]"
    raise TypeError(f"cannot write {type(value).__name__} as JSON")


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, list):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def key_text(identifier: Any) -> str:
    if isinstance(identifier, bool) or identifier is None:
        raise ValueError(f"invalid record key {identifier!r}")
    return plain(identifier) if isinstance(identifier, (int, float)) else str(identifier)


def _order(identifier: Any) -> tuple[int, Any]:
    return (0, identifier) if isinstance(identifier, (int, float)) and not isinstance(identifier, bool) else (1, str(identifier))


# ---------------------------------------------------------------- connection


class Client:
    """The query and document API (url) and the config server (config_url) of one Vespa application; an optional bearer token."""

    def __init__(self, url: str, config_url: str, token: str | None, timeout: float) -> None:
        self.url = url.rstrip("/")
        self.config_url = config_url.rstrip("/")
        self.token = token
        self.timeout = timeout

    def request(self, method: str, base: str, path: str, query: dict[str, Any] | None = None, body: bytes | None = None,
                content_type: str = "application/json", timeout: float | None = None) -> tuple[int, Any]:
        """One HTTP request; returns the status and the decoded JSON (or text) of the answer, for every status."""
        address = base + path
        if query:
            address += "?" + urllib.parse.urlencode({name: _parameter(item) for name, item in query.items()})
        request = urllib.request.Request(address, data=body, method=method)
        if body is not None:
            request.add_header("Content-Type", content_type)
        if self.token:
            request.add_header("Authorization", "Bearer " + self.token)
        try:
            with urllib.request.urlopen(request, timeout=timeout or self.timeout) as response:
                return response.status, _decode(response.read())
        except urllib.error.HTTPError as error:
            return error.code, _decode(error.read())
        except (urllib.error.URLError, ConnectionError, TimeoutError) as error:
            raise VespaError(f"{method} {address} failed: {error}") from error

    def close(self) -> None:
        pass


def _parameter(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    return plain(value) if isinstance(value, (int, float)) else str(value)


def _decode(data: bytes) -> Any:
    text = data.decode("utf-8", errors="replace")
    try:
        return json.loads(text) if text.strip() else None
    except json.JSONDecodeError:
        return text


def connect(url: str, config_url: str, token_variable: str = "VECDSL_VESPA_TOKEN", timeout: float = 30.0) -> Client:
    return Client(url, config_url, os.environ.get(token_variable) or None, timeout)


def _retried(client: Client, method: str, base: str, path: str, query: dict[str, Any] | None = None, body: bytes | None = None,
             content_type: str = "application/json", timeout: float | None = None) -> tuple[int, Any]:
    """A request repeated while the server answers 429 or 503 (too many operations, or a cluster still starting), at most 60 s."""
    deadline = time.monotonic() + _RETRY_TIMEOUT
    delay = 0.2
    while True:
        status, answer = client.request(method, base, path, query, body, content_type, timeout)
        if status not in (429, 503) or time.monotonic() > deadline:
            return status, answer
        time.sleep(delay)
        delay = min(delay * 2, 2.0)


def _fail(what: str, status: int, answer: Any) -> NoReturn:
    message = answer.get("message") if isinstance(answer, dict) else answer
    raise VespaError(f"{what} failed with HTTP {status}: {message}", status)


# ---------------------------------------------------------------- deployment


def _deployed(client: Client) -> list[str] | None:
    """The document types of the active application (its schema files), or None without an application."""
    status, answer = client.request("GET", client.config_url, "/application/v2/tenant/default/application/")
    if status != 200:
        _fail("listing the applications", status, answer)
    if not answer:
        return None
    status, answer = client.request("GET", client.config_url, _INSTANCE + "/content/schemas/")
    if status == 404:
        return []
    if status != 200:
        _fail("reading the deployed schemas", status, answer)
    names = [entry.rstrip("/").rsplit("/", 1)[-1] for entry in answer]
    return sorted(name[:-3] for name in names if name.endswith(".sd"))


def _zip(files: dict[str, str]) -> bytes:
    """The package as a zip archive with fixed timestamps, stored (not compressed)."""
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_STORED) as archive:
        for name, text in files.items():
            info = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
            info.external_attr = 0o644 << 16
            archive.writestr(info, text.encode("utf-8"))
    return buffer.getvalue()


def deploy(client: Client, files: dict[str, str], overrides: str | None = None, created: Sequence[str] = (),
           skip_existing: bool = False, dropped: Sequence[str] = (), ignore_missing: bool = False) -> None:
    """
    Deploys the package as the program's statements leave it. A created type that is already deployed fails the statement (or,
    with skip_existing, leaves the application as it is); a dropped type that is not deployed fails it unless ignore_missing; the
    documents of a deployed dropped type are deleted first. No files: the application is removed.
    """
    present = _deployed(client)
    deployed = present or []
    for name in created:
        if name in deployed:
            if skip_existing:
                return
            raise ConflictError(f"collection {name} already exists")
    for name in dropped:
        if name not in deployed and not ignore_missing:
            raise VespaError(f"collection {name} does not exist")
    for name in dropped:
        if name in deployed:
            _delete_all(client, name)
    if not files:
        if present is not None:
            status, answer = client.request("DELETE", client.config_url, _APPLICATION, timeout=_DEPLOY_TIMEOUT)
            if status not in (200, 404):
                _fail("removing the application", status, answer)
        return
    package = dict(files)
    if overrides is not None:
        until = (datetime.datetime.now(datetime.timezone.utc).date() + datetime.timedelta(days=1)).isoformat()
        package["validation-overrides.xml"] = overrides.replace(_UNTIL, until)
    status, answer = client.request("POST", client.config_url, "/application/v2/tenant/default/prepareandactivate", body=_zip(package),
                                    content_type="application/zip", timeout=_DEPLOY_TIMEOUT)
    if status != 200:
        _fail("deploying the application package", status, answer)
    session = int(answer["session-id"])
    deadline = time.monotonic() + _DEPLOY_TIMEOUT
    _await_converged(client, session, deadline)
    types = [name[len("schemas/"):-3] for name in files if name.startswith("schemas/") and name.endswith(".sd")]
    _await_serving(client, types, time.monotonic() + _READY_TIMEOUT)


def _await_converged(client: Client, session: int, deadline: float) -> None:
    """Polls serviceconverge until every service runs the deployed session's config generation."""
    last: Any = None
    while True:
        status, answer = client.request("GET", client.config_url, _INSTANCE + "/serviceconverge")
        last = answer
        if status == 200 and isinstance(answer, dict) and answer.get("converged") and int(answer.get("currentGeneration", 0)) >= session:
            return
        if time.monotonic() > deadline:
            raise TimeoutError(f"the application did not converge on session {session} within {_DEPLOY_TIMEOUT:.0f} s "
                               f"(serviceconverge: {last})")
        time.sleep(_POLL)


def _await_serving(client: Client, types: Sequence[str], deadline: float) -> None:
    """Waits until the container answers /status.html and each document type answers a query and a document lookup."""
    pending = ["/status.html", *types]
    while pending:
        target = pending[0]
        try:
            if target == "/status.html":
                status, answer = client.request("GET", client.url, "/status.html")
                ready = status == 200
            else:
                status, answer = client.request("POST", client.url, "/search/", body=dumps(
                    {"yql": f"select * from {target} where true", "hits": 0}).encode("utf-8"))
                ready = status == 200 and not (isinstance(answer, dict) and answer.get("root", {}).get("errors"))
                if ready:
                    status, answer = client.request("GET", client.url, _path(target, "vecdsl-readiness-probe"), {"format.tensors": "short-value"})
                    ready = status in (200, 404)
        except VespaError as error:
            ready, answer = False, str(error)
        if ready:
            pending.pop(0)
            continue
        if time.monotonic() > deadline:
            raise TimeoutError(f"the application did not serve {target} within {_READY_TIMEOUT:.0f} s (last answer: {answer})")
        time.sleep(_POLL)


def await_ready(client: Client, document_type: str, timeout: float = _READY_TIMEOUT) -> dict[str, Any]:
    """Waits until the deployment has converged and the document type serves queries, at most timeout seconds."""
    deadline = time.monotonic() + timeout
    status, answer = client.request("GET", client.config_url, _APPLICATION)
    if status != 200:
        _fail("reading the application", status, answer)
    _await_converged(client, int(answer.get("generation", 0)), deadline)
    _await_serving(client, [document_type], deadline)
    return {"collection": document_type, "state": "ready"}


def require_collection(client: Client, document_type: str) -> None:
    if document_type not in (_deployed(client) or []):
        raise VespaError(f"collection {document_type} does not exist")


def reindex(client: Client, document_type: str, timeout: float = _DEPLOY_TIMEOUT) -> dict[str, Any]:
    """Triggers reindexing of the document type and polls the reindexing status until it succeeds, at most timeout seconds."""
    require_collection(client, document_type)
    status, answer = client.request("POST", client.config_url, _INSTANCE + "/reindex",
                                    {"clusterId": CLUSTER, "documentType": document_type})
    if status != 200:
        _fail("triggering reindexing", status, answer)
    deadline = time.monotonic() + timeout
    while True:
        status, answer = client.request("GET", client.config_url, _INSTANCE + "/reindexing")
        state = None
        if status == 200 and isinstance(answer, dict):
            state = answer.get("clusters", {}).get(CLUSTER, {}).get("ready", {}).get(document_type, {}).get("state")
        if state == "successful":
            return {"collection": document_type, "state": state}
        if state == "failed":
            raise VespaError(f"reindexing {document_type} failed: {answer}")
        if time.monotonic() > deadline:
            raise TimeoutError(f"reindexing {document_type} did not finish within {timeout:.0f} s (state {state})")
        time.sleep(_POLL)


def describe(client: Client, document_type: str, stats: dict[str, Any] | None = None, progress: bool = False) -> dict[str, Any]:
    """The deployed schema of the collection, its document count on request, and whether the deployment has converged."""
    status, answer = client.request("GET", client.config_url, _INSTANCE + f"/content/schemas/{document_type}.sd")
    if status != 200:
        _fail(f"reading the schema of {document_type}", status, answer)
    result: dict[str, Any] = {"name": document_type, "schema": answer}
    if stats is not None:
        result["count"] = count(client, **stats)
    if progress:
        status, converge = client.request("GET", client.config_url, _INSTANCE + "/serviceconverge")
        result["converged"] = bool(status == 200 and isinstance(converge, dict) and converge.get("converged"))
    return result


def names(client: Client, kind: str, prefix: str | None = None, limit: int | None = None, database: str | None = None,
          names: Sequence[str] | None = None, body: dict[str, Any] | None = None) -> list[str]:  # noqa: A002
    """collections and databases (the deployed schemas), the program's index names, and the values of a slice attribute (grouping)."""
    if kind in ("collections", "databases"):
        types = _deployed(client) or []
        if kind == "databases":
            found = sorted({name.split("_", 1)[0] for name in types if "_" in name})
        elif database is not None:
            found = [name[len(database) + 1:] for name in types if name.startswith(database + "_")]
        else:
            found = list(types)
    elif kind == "indexes":
        found = list(names or [])
    else:
        root = _query(client, body or {})
        found = []
        for group_list in root.get("children", []):
            for list_node in group_list.get("children", []):
                for group in list_node.get("children", []):
                    # a document without the slice has the empty string in the attribute, which is not a slice name
                    if group.get("value") not in (None, ""):
                        found.append(str(group["value"]))
    found = sorted(name for name in found if prefix is None or name.startswith(prefix))
    return found if limit is None else found[:limit]


# ---------------------------------------------------------------- documents


def _path(document_type: str, key: Any) -> str:
    return f"/document/v1/{NAMESPACE}/{document_type}/docid/" + urllib.parse.quote(key_text(key), safe="")


def _fields(record: dict[str, Any], key: str, vectors: dict[str, int] | None, slices: dict[str, Any] | None) -> dict[str, Any]:
    if record.get(key) is None:
        raise ValueError(f"a record without its key field {key}")
    fields = {name: item for name, item in record.items() if item is not None}
    for name, dim in (vectors or {}).items():
        if name in fields and len(fields[name]) != dim:
            raise ValueError(f"vector field {name} has {len(fields[name])} dimensions, the schema expects {dim}")
    fields.update(slices or {})
    return fields


def _get(client: Client, document_type: str, key: Any) -> dict[str, Any] | None:
    status, answer = _retried(client, "GET", client.url, _path(document_type, key), {"format.tensors": "short-value"})
    if status == 404:
        return None
    if status != 200:
        _fail(f"reading document {key_text(key)}", status, answer)
    return answer.get("fields", {})


def _expired(fields: dict[str, Any], now: int) -> bool:
    return fields.get(EXPIRES) is not None and fields[EXPIRES] <= now


def write(client: Client, document_type: str, key: str, records: Sequence[dict[str, Any]], policy: str, counter: str,
          vectors: dict[str, int] | None = None, slices: dict[str, Any] | None = None, expiring: bool = False, ttl: int | None = None,
          versioned: bool = False) -> dict[str, int]:
    """
    Puts each record as a document. error: every id is read first and any existing one fails the write before anything is written;
    error and ignore then put with the condition false and create (an existing document answers 412); replace puts unconditionally.
    """
    now = int(time.time())
    documents = []
    for record in records:
        fields = _fields(record, key, vectors, slices)
        if expiring:
            fields[EXPIRES] = now + ttl if ttl is not None else NO_EXPIRY
        if versioned:
            fields[VERSION] = 1
        documents.append((record[key], fields))
    if policy == "error":
        existing = [key_text(identifier) for identifier, _ in documents
                    if (found := _get(client, document_type, identifier)) is not None and not _expired(found, now)]
        if existing:
            raise ConflictError(f"records with these ids exist already: {', '.join(existing)}; nothing was written")
    written = 0
    for identifier, fields in documents:
        operation: dict[str, Any] = {"fields": fields}
        if policy in ("error", "ignore"):
            operation = {"condition": "false", "create": True, "fields": fields}
        status, answer = _retried(client, "POST", client.url, _path(document_type, identifier), body=dumps(operation).encode("utf-8"))
        if status == 412:
            if policy == "ignore":
                continue
            raise ConflictError(f"record {key_text(identifier)} exists already")
        if status != 200:
            _fail(f"writing document {key_text(identifier)}", status, answer)
        written += 1
    return {counter: written}


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return json.loads(stripped)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, location: str, document_type: str, key: str, policy: str, counter: str,
                vectors: dict[str, int] | None = None, slices: dict[str, Any] | None = None, expiring: bool = False,
                ttl: int | None = None, versioned: bool = False) -> dict[str, int]:
    return write(client, document_type, key, read_records(client, location), policy, counter, vectors, slices, expiring, ttl, versioned)


def _selected(client: Client, key: str, select: dict[str, Any], limit: int | None) -> list[Any]:
    """The keys of the documents a query selects, in key order: every page, or the first limit keys."""
    keys: list[Any] = []
    while True:
        page = dict(select)
        body = dict(page["body"])
        wanted = _PAGE if limit is None else min(_PAGE, limit - len(keys))
        body["hits"] = wanted
        body["offset"] = len(keys)
        page["body"] = body
        found = [hit["fields"].get(key) for hit in _hits(_query(client, **page))]
        keys.extend(found)
        if len(found) < wanted or (limit is not None and len(keys) >= limit):
            return keys


def update(client: Client, document_type: str, key: str, ids: Sequence[Any] | None = None, select: dict[str, Any] | None = None,
           records: Sequence[dict[str, Any]] | None = None, set: dict[str, Any] | None = None,  # noqa: A002
           append: dict[str, Any] | None = None, remove: dict[str, Any] | None = None, clear: Sequence[str] | None = None,
           vectors: dict[str, int] | None = None, version: int | None = None, versioned: bool = False) -> dict[str, int]:
    """Partial updates by id, each conditional on the document existing (or on its version), so missing documents are not counted."""
    condition = f"{document_type}.{VERSION}=={version}" if version is not None else document_type
    changes: list[tuple[Any, dict[str, Any]]] = []
    if records is not None:
        for record in records:
            fields = _fields(record, key, vectors, None)
            changes.append((record[key], {name: {"assign": item} for name, item in fields.items() if name != key}))
    else:
        operations: dict[str, Any] = {}
        for name, item in (set or {}).items():
            if name in (vectors or {}) and len(item) != vectors[name]:
                raise ValueError(f"vector field {name} has {len(item)} dimensions, the schema expects {vectors[name]}")
            operations[name] = {"assign": item}
        for name, items in (append or {}).items():
            operations[name] = {"add": items}
        for name, items in (remove or {}).items():
            operations[name] = {"remove": items}
        for name in clear or ():
            operations[name] = {"assign": None}
        targets = list(ids) if ids is not None else _selected(client, key, select or {}, None)
        changes = [(identifier, operations) for identifier in targets]
    updated = 0
    for identifier, operations in changes:
        fields = dict(operations)
        if versioned:
            fields[VERSION] = {"increment": 1}
        body = {"condition": condition, "fields": fields}
        status, answer = _retried(client, "PUT", client.url, _path(document_type, identifier), body=dumps(body).encode("utf-8"))
        if status == 412:
            continue
        if status != 200:
            _fail(f"updating document {key_text(identifier)}", status, answer)
        updated += 1
    return {"update_count": updated}


def delete(client: Client, document_type: str, key: str, ids: Sequence[Any] | None = None, select: dict[str, Any] | None = None,
           limit: int | None = None, all: bool = False) -> dict[str, int]:  # noqa: A002
    """Removes documents by id (conditional on the type, so missing ids are not counted), selected by a query, or every document."""
    if all:
        return {"delete_count": _delete_all(client, document_type)}
    targets = list(ids) if ids is not None else _selected(client, key, select or {}, limit)
    deleted = 0
    for identifier in targets:
        status, answer = _retried(client, "DELETE", client.url, _path(document_type, identifier), {"condition": document_type})
        if status == 412:
            continue
        if status != 200:
            _fail(f"deleting document {key_text(identifier)}", status, answer)
        deleted += 1
    return {"delete_count": deleted}


def _delete_all(client: Client, document_type: str) -> int:
    """Delete where the selection is true over the type's documents, chunk by chunk; returns how many there were."""
    total = count(client, {"yql": f"select * from {document_type} where true", "hits": 0})
    continuation: str | None = None
    while True:
        query = {"selection": "true", "cluster": CLUSTER}
        if continuation:
            query["continuation"] = continuation
        status, answer = _retried(client, "DELETE", client.url, f"/document/v1/{NAMESPACE}/{document_type}/docid", query,
                                  timeout=_DEPLOY_TIMEOUT)
        if status != 200:
            _fail(f"deleting the documents of {document_type}", status, answer)
        continuation = answer.get("continuation") if isinstance(answer, dict) else None
        if not continuation:
            return total


def expire(client: Client, document_type: str, seconds: int) -> dict[str, int]:
    """Sets the expiry time of every existing document (an update where the selection is true); returns how many there were."""
    total = count(client, {"yql": f"select * from {document_type} where true", "hits": 0})
    body = dumps({"fields": {EXPIRES: {"assign": int(time.time()) + seconds}}}).encode("utf-8")
    continuation: str | None = None
    while True:
        query = {"selection": "true", "cluster": CLUSTER}
        if continuation:
            query["continuation"] = continuation
        status, answer = _retried(client, "PUT", client.url, f"/document/v1/{NAMESPACE}/{document_type}/docid", query, body,
                                  timeout=_DEPLOY_TIMEOUT)
        if status != 200:
            _fail(f"setting the expiry of {document_type}", status, answer)
        continuation = answer.get("continuation") if isinstance(answer, dict) else None
        if not continuation:
            return {"expire_count": total}


def get(client: Client, document_type: str, key: str, ids: Sequence[Any], output: Sequence[str], vectors: Sequence[str] = (),
        slices: dict[str, Sequence[Any]] | None = None, expiring: bool = False) -> list[dict[str, Any]]:
    """Documents by id, in the order of the ids; missing documents, documents outside the slices and expired ones are skipped."""
    now = int(time.time())
    hits = []
    for identifier in ids:
        fields = _get(client, document_type, identifier)
        if fields is None or (expiring and _expired(fields, now)):
            continue
        if any(fields.get(name) not in allowed for name, allowed in (slices or {}).items()):
            continue
        hits.append(_project(fields, key, output, vectors, None))
    return hits


# ---------------------------------------------------------------- queries


def _marked(text: Any) -> bool:
    """A highlight fragment counts only with a bolded term: Vespa also returns the bolded summary field, unmarked, in hits
    that matched no term (the vector leg of a hybrid search, a summary filled without the query terms)."""
    return isinstance(text, str) and BOLD in text


def _project(fields: dict[str, Any], key: str, output: Sequence[str], vectors: Sequence[str], score: float | None,
             highlight: Sequence[str] | None = None, explanation: Any = None) -> dict[str, Any]:
    hit: dict[str, Any] = {"id": fields.get(key)}
    if score is not None:
        hit["score"] = score
    for name in [*output, *vectors]:
        hit[name] = fields.get(name)
    if highlight:
        hit["highlight"] = {name: [fields[HIGHLIGHT + name]] for name in highlight if _marked(fields.get(HIGHLIGHT + name))}
    if explanation is not None:
        hit["explanation"] = explanation
    return _value(hit)


def _query(client: Client, body: dict[str, Any], texts: dict[str, Any] | None = None, numbers: dict[str, Any] | None = None,
           flags: dict[str, Any] | None = None, clock: bool = False) -> dict[str, Any]:
    """POST /search/ with the generated body and the bound values, each checked against the type its @reference expects."""
    request = dict(body)
    for name, item in (texts or {}).items():
        if not isinstance(item, str):
            raise TypeError(f"query parameter {name} must be a string, not {type(item).__name__}")
        request[name] = item
    for name, item in (numbers or {}).items():
        if isinstance(item, bool) or not isinstance(item, (int, float)) or not math.isfinite(item):
            raise TypeError(f"query parameter {name} must be a finite number, not {item!r}")
        request[name] = item
    for name, item in (flags or {}).items():
        if not isinstance(item, bool):
            raise TypeError(f"query parameter {name} must be a boolean, not {item!r}")
        request[name] = item
    if clock:
        request["vecdsl_now"] = int(time.time())
    status, answer = _retried(client, "POST", client.url, "/search/", body=dumps(request).encode("utf-8"))
    root = answer.get("root", {}) if isinstance(answer, dict) else {}
    if status != 200 or root.get("errors"):
        _fail("the query", status, root.get("errors") if root.get("errors") else answer)
    return root


def _hits(root: dict[str, Any]) -> list[dict[str, Any]]:
    """The hits of a result: every child with fields except grouping nodes. A hit filled from a document summary without
    documentid has an id of the form index:<cluster>/<part>/<gid> instead of id:..., so the id prefix is not a test."""
    return [child for child in root.get("children", []) if "fields" in child and not str(child.get("id", "")).startswith("group:")]


def _vector(client: Client, document_type: str, field: str, identifier: Any) -> list[float]:
    fields = _get(client, document_type, identifier)
    if fields is None or fields.get(field) is None:
        raise ValueError(f"no vector {field} stored for id {key_text(identifier)} in {document_type}")
    return fields[field]


def _query_vector(client: Client, body: dict[str, Any], lookup: dict[str, Any] | None) -> dict[str, Any]:
    """The body with input.query(vecdsl_q): given, a stored document's vector, or 2 avg(positive) - avg(negative) of the examples."""
    if lookup is None:
        return body
    positives = [*lookup.get("positive_vectors", [])]
    negatives = [*lookup.get("negative_vectors", [])]
    positives += [_vector(client, lookup["document_type"], lookup["field"], identifier) for identifier in lookup.get("positive_ids", [])]
    negatives += [_vector(client, lookup["document_type"], lookup["field"], identifier) for identifier in lookup.get("negative_ids", [])]
    if not positives:
        raise ValueError("no positive example to search with")
    dim = len(positives[0])
    mean = [sum(vector[i] for vector in positives) / len(positives) for i in range(dim)]
    if negatives:
        negative = [sum(vector[i] for vector in negatives) / len(negatives) for i in range(dim)]
        mean = [2 * mean[i] - negative[i] for i in range(dim)]
    result = dict(body)
    inputs = dict(result.get("input", {}))
    inputs["query(vecdsl_q)"] = mean
    result["input"] = inputs
    return result


def _similarity(distance: float, metric: str) -> float:
    """Canonical similarity from a Vespa distance: cosine from the angle, the negated distance for euclidean and hamming, dot from -dot."""
    if metric == "cosine":
        return math.cos(distance)
    return -distance


def _closeness_distance(hit: dict[str, Any], search: dict[str, Any]) -> float | None:
    """The distance from the relevance of a hit ranked by a generated vecdsl_nn_ profile (first phase closeness = 1 / (1 + distance)).
    Grouping hits (output(summary())) carry no match features, only the relevance."""
    profile = (search.get("body", {}).get("ranking") or {}).get("profile", "")
    relevance = hit.get("relevance")
    if not str(profile).startswith("vecdsl_nn_") or search.get("metric") not in ("cosine", "euclidean", "hamming") \
            or not isinstance(relevance, (int, float)) or relevance <= 0:
        return None
    return 1.0 / float(relevance) - 1.0


def _score(hit: dict[str, Any], search: dict[str, Any]) -> float | None:
    """The canonical score of a hit (from the distance match feature), the native relevance, or no score."""
    if search.get("scores") is False:
        return None
    if search.get("feature") and not search.get("native"):
        distance = hit["fields"].get("matchfeatures", {}).get(search["feature"])
        if distance is None:
            distance = _closeness_distance(hit, search)
        if distance is None:
            raise VespaError(f"hit {hit.get('id')} has no match feature {search['feature']}")
        return _similarity(float(distance), search["metric"])
    return float(hit.get("relevance", 0.0))


def _root(client: Client, search: dict[str, Any]) -> dict[str, Any]:
    body = _query_vector(client, search["body"], search.get("lookup"))
    return _query(client, body, search.get("texts"), search.get("numbers"), search.get("flags"), bool(search.get("clock")))


def _scored(client: Client, search: dict[str, Any]) -> list[tuple[dict[str, Any], float | None]]:
    """The hits of one query, best first, with their canonical score (or the native relevance), or no score."""
    return [(hit["fields"], _score(hit, search)) for hit in _hits(_root(client, search))]


def _groups(client: Client, search: dict[str, Any]) -> list[tuple[Any, list[tuple[dict[str, Any], float | None]]]]:
    """The groups of a query whose YQL ends in all(group(f) max(n) each(max(m) each(output(summary())))), in Vespa's order."""
    groups = []
    for top in _root(client, search).get("children", []):
        if not str(top.get("id", "")).startswith("group:root"):
            continue
        for group_list in top.get("children", []):
            for group in group_list.get("children", []):
                hits = [(hit["fields"], _score(hit, search)) for hit_list in group.get("children", [])
                        for hit in hit_list.get("children", []) if "fields" in hit]
                groups.append((group.get("value"), hits))
    return groups


def _sort_key(value: Any) -> tuple[int, Any]:
    return (1, value) if isinstance(value, str) else (0, float(value))


def _sorted(found: list[tuple[dict[str, Any], float | None]], order: Sequence[Sequence[Any]]) -> list[tuple[dict[str, Any], float | None]]:
    """Hits ordered by the sort keys (None names the score), missing values last, the earlier order breaking ties."""
    result = list(found)
    for name, direction in reversed(order):
        def value(item: tuple[dict[str, Any], float | None], field: str | None = name) -> Any:
            return item[1] if field is None else item[0].get(field)
        present = [item for item in result if value(item) is not None]
        present.sort(key=lambda item: _sort_key(value(item)), reverse=direction == "desc")
        result = present + [item for item in result if value(item) is None]
    return result


def _in_slice(identifier: Any, part: Sequence[int]) -> bool:
    """Slice i of n: the first 28 bits of the md5 of the key text, modulo n, are i (the same slices on every target)."""
    return int(hashlib.md5(key_text(identifier).encode("utf-8")).hexdigest()[:7], 16) % part[1] == part[0]


def _stream(client: Client, search: dict[str, Any], key: str, every: bool, after: Any, part: Sequence[int] | None,
            limit: int | None, offset: int) -> list[tuple[dict[str, Any], float | None]]:
    """Pages of a query in result order: every page, or the hits after the cursor record and in the slice, offset and limit applied."""
    body = search["body"]
    size = int(body["hits"])
    plain_pages = after is None and part is None
    start = int(body.get("offset", 0)) if plain_pages else 0
    passed = after is None
    found: list[tuple[dict[str, Any], float | None]] = []
    while True:
        batch = _scored(client, dict(search, body=dict(body, offset=start)))
        start += len(batch)
        for fields, score in batch:
            if not passed:
                passed = key_text(fields.get(key)) == key_text(after)
            elif part is None or _in_slice(fields.get(key), part):
                found.append((fields, score))
        if len(batch) < size or (not every and limit is not None and len(found) >= offset + limit):
            break
    if plain_pages:
        return found
    return found[offset:] if limit is None else found[offset:offset + limit]


def _within(score: float | None, low: float | None, high: float | None) -> bool:
    return score is None or ((low is None or score >= low) and (high is None or score <= high))


def search(client: Client, body: dict[str, Any], key: str, output: Sequence[str], texts: dict[str, Any] | None = None,
           numbers: dict[str, Any] | None = None, flags: dict[str, Any] | None = None, clock: bool = False,
           vectors: Sequence[str] = (), metric: str | None = None, feature: str | None = None, native: bool = False,
           low: float | None = None, high: float | None = None, lookup: dict[str, Any] | None = None,
           total: dict[str, Any] | None = None, scores: bool = True, every: bool = False, after: Any = None,
           slice: Sequence[int] | None = None, order: Sequence[Sequence[Any]] | None = None, groups: dict[str, Any] | None = None,  # noqa: A002
           highlight: Sequence[str] | None = None, limit: int | None = None, offset: int = 0) -> Any:
    """A query built by the generator: the hits (id, score, output fields, vector fields), or {hits, total} with total; every: all pages;
    after: the hits after the cursor record; slice: [i, n]; order: sort keys over the selected hits; groups: Vespa's groups."""
    search_args = {"body": body, "texts": texts, "numbers": numbers, "flags": flags, "clock": clock, "metric": metric,
                   "feature": feature, "native": native, "lookup": lookup, "scores": scores}
    result: list[Any]
    if groups is not None:
        result = [{"group": _value(value), "hits": [_project(fields, key, output, vectors, score, highlight, fields.get("rankfeatures"))
                                                     for fields, score in hits if _within(score, low, high)]}
                  for value, hits in _groups(client, search_args)[int(groups.get("offset", 0)):]]
    else:
        if every or after is not None or slice is not None:
            found = _stream(client, search_args, key, every, after, slice, limit, offset)
        else:
            found = _scored(client, search_args)
        found = [item for item in found if _within(item[1], low, high)]
        if order:
            found = _sorted(found, order)
        result = [_project(fields, key, output, vectors, score, highlight, fields.get("rankfeatures")) for fields, score in found]
    return result if total is None else {"hits": result, "total": count(client, **total)}


def hybrid(client: Client, legs: Sequence[dict[str, Any]], fusion: str, key: str, output: Sequence[str], limit: int,
           offset: int = 0, k: int = 60, weights: Sequence[float] | None = None, vectors: Sequence[str] = (),
           low: float | None = None, high: float | None = None, after: Any = None, order: Sequence[Sequence[Any]] | None = None,
           groups: dict[str, Any] | None = None, highlight: Sequence[str] | None = None, explain: bool = False,
           total: dict[str, Any] | None = None) -> Any:
    """Legs queried one by one and fused as vecDSL defines rrf (sum of 1/(k + rank)), weighted and relative_score; ties by key. after: the
    hits after the cursor record; groups: the fused hits grouped by a field; explain: each leg's rank features; total: {hits, total}."""
    weights = weights or [1.0] * len(legs)
    fused: dict[str, float] = {}
    documents: dict[str, dict[str, Any]] = {}
    explained: dict[str, list[Any]] = {}
    for index, (leg, weight) in enumerate(zip(legs, weights)):
        scored = _scored(client, leg)
        values = [(fields, score if score is not None else 0.0) for fields, score in scored]
        if fusion == "relative_score" and values:
            least, most = min(value for _, value in values), max(value for _, value in values)
            values = [(fields, 1.0 if most == least else (value - least) / (most - least)) for fields, value in values]
        for rank, (fields, value) in enumerate(values, start=1):
            name = key_text(fields.get(key))
            merged = documents.setdefault(name, {})
            for field, item in fields.items():
                if field.startswith(HIGHLIGHT) and _marked(item):
                    merged[field] = item  # the keyword leg's bolded fragment wins over the vector leg's unmarked one
                else:
                    merged.setdefault(field, item)
            if explain:
                explained.setdefault(name, [None] * len(legs))[index] = fields.get("rankfeatures")
            part = 1.0 / (k + rank) if fusion == "rrf" else weight * value
            fused[name] = fused.get(name, 0.0) + part
    ranked = sorted(documents, key=lambda name: (-fused[name], _order(documents[name].get(key))))
    ranked = [name for name in ranked if (low is None or fused[name] >= low) and (high is None or fused[name] <= high)]
    if after is not None:
        ranked = ranked[ranked.index(key_text(after)) + 1:] if key_text(after) in ranked else []

    def hit(name: str) -> dict[str, Any]:
        return _project(documents[name], key, output, vectors, fused[name], highlight, explained.get(name))
    result: list[Any]
    if groups is not None:
        members: dict[str, list[str]] = {}
        labels: dict[str, Any] = {}
        for name in ranked:
            label = documents[name].get(groups["field"])
            if label is None:
                continue
            group = dumps(label)
            labels.setdefault(group, label)
            if len(members.setdefault(group, [])) < int(groups.get("size", 1)):
                members[group].append(name)
        result = [{"group": _value(labels[group]), "hits": [hit(name) for name in names]}
                  for group, names in members.items()][offset:offset + limit]
    else:
        page = ranked[offset:offset + limit]
        if order:
            page = [key_text(fields.get(key)) for fields, _ in _sorted([(documents[name], fused[name]) for name in page], order)]
        result = [hit(name) for name in page]
    return result if total is None else {"hits": result, "total": count(client, **total)}


def count(client: Client, body: dict[str, Any], texts: dict[str, Any] | None = None, numbers: dict[str, Any] | None = None,
          flags: dict[str, Any] | None = None, clock: bool = False) -> int:
    """The totalCount of a query without hits (exact for filters; a count never uses nearestNeighbor)."""
    return int(_query(client, body, texts, numbers, flags, clock).get("fields", {}).get("totalCount", 0))


def distance_matrix(client: Client, body: dict[str, Any], key: str, field: str, metric: str, limit: int,
                    texts: dict[str, Any] | None = None, numbers: dict[str, Any] | None = None, flags: dict[str, Any] | None = None,
                    clock: bool = False) -> list[dict[str, Any]]:
    """Each sampled record with its nearest neighbours among the sample (canonical similarity, computed in the runtime)."""
    sample = [fields for fields, _ in _scored(client, {"body": body, "texts": texts, "numbers": numbers, "flags": flags,
                                                       "clock": clock, "scores": False}) if fields.get(field)]
    pairs = []
    for left in sample:
        scored = []
        for right in sample:
            if right is left:
                continue
            u, v = left[field], right[field]
            if metric == "euclidean":
                value = -math.sqrt(sum((a - b) ** 2 for a, b in zip(u, v)))
            elif metric == "dot":
                value = sum(a * b for a, b in zip(u, v))
            elif metric == "hamming":
                value = -float(sum(bin((int(a) ^ int(b)) & 0xFF).count("1") for a, b in zip(u, v)))
            else:
                norms = math.sqrt(sum(a * a for a in u)) * math.sqrt(sum(b * b for b in v))
                value = sum(a * b for a, b in zip(u, v)) / norms if norms else 0.0
            scored.append((value, right))
        scored.sort(key=lambda item: (-item[0], _order(item[1].get(key))))
        pairs.extend({"a": left.get(key), "b": right.get(key), "score": value} for value, right in scored[:limit])
    return _value(pairs)
